export type AppErrorCode =
  | 'AUTH_INVALID'
  | 'AUTH_PERMANENT'
  | 'TIMEOUT'
  | 'RATE_LIMIT'
  | 'PERMISSION'
  | 'CHANNEL_UNAVAILABLE'
  | 'CONVERSATION_STATE'
  | 'NETWORK'
  | 'CONFIG'
  | 'GATEWAY'
  | 'BILLING'
  | 'OVERLOADED'
  | 'MODEL_NOT_FOUND'
  | 'UNKNOWN';

/**
 * Every class the unified exit can render. Kept as a runtime list so copy,
 * retry and locale coverage can be audited exhaustively instead of by memory.
 */
export const APP_ERROR_CODES = [
  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** Fixed, non-executable actions that a renderer may offer to the user. */
export type AppErrorActionKind =
  | 'retry'
  | 'reauthenticate'
  | 'reconfigure'
  | 'open-settings'
  | 'contact-support';

/** A closed set of targets so actions cannot become arbitrary commands. */
export type AppErrorActionTarget =
  | 'authentication'
  | 'billing'
  | 'configuration'
  | 'conversation'
  | 'model'
  | 'permissions';

ex**
 * An action is data, never a command. The optional target is selected from a
 * closed vocabulary; command, script, shell, exec and argv are intentionally
 * not representable.
 */
export type AppErrorNextAction =
  | { kind: 'retry' }
  | { kind: 'reauthenticate'; target?: 'authentication' }
  | { kind: 'reconfigure'; target?: 'configuration' | 'conversation' | 'model' }
  | { kind: 'open-settings'; target?: 'authentication' | 'billing' | 'permissions' }
  | { kind: 'contact-support' };

/** Recovery authority for an error class. */
export type AppErrorRecoveryScope =
  | 'self-retry'
  | 'user-action-required'
  | 'support-required'
  | 'expose-raw-error';

export type AppErrorRecovery = {
  readonly retryable: boolean;
  readonly scope: AppErrorRecoveryScope;
  readonly action?: AppErrorNextAction;
};

/**
 * Exhaustive recovery governance. Every AppErrorCode has exactly one stable
 * entry. Only transient classes may self-retry; all other entries require a
 * user, support, or raw-error outcome and never claim to be automatically
 * repairable.
 */
export const APP_ERROR_RECOVERY: Readonly<Record<AppErrorCode, AppErrorRecovery>> = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  TIMEOUT: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  PERMISSION: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'open-settings', target: 'permissions' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reconfigure', target: 'conversation' },
  },
  NETWORK: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  CONFIG: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reconfigure', target: 'configuration' },
  },
  GATEWAY: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  BILLING: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'open-settings', target: 'billing' },
  },
  OVERLOADED: {
    retryable: true,
    scope: 'self-retry',
    action: { kind: 'retry' },
  },
  MODEL_NOT_FOUND: {
    retryable: false,
    scope: 'user-action-required',
    action: { kind: 'reconfigure', target: 'model' },
  },
  UNKNOWN: {
    retryable: false,
    scope: 'expose-raw-error',
