export class AppError extends Error {
  code: AppErrorCode;
  cause?: unknown;
  details?: Record<string, unknown>;
  /** Renderer-side correlation id echoed by the Main host dispatcher. */
  requestId?: string;
  readonly retryable: boolean;
  readonly nextAction?: AppErrorNextAction;

  constructor(
    code: AppErrorCode,
    message: string,
    cause?: unknown,
    details?: Record<string, unknown>,
    requestId?: string,
  ) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.cause = cause;
    this.details = details;
    this.requestId = requestId;
    const recovery = APP_ERROR_RECOVERY[code];
    this.retryable = recovery.retryable;
    this.nextAction = recovery.action;
  }
}

/**
 * Structured facts read off the thrown value and its cause/response chain.
 *
 * Classification reads these first; it only falls back to the raw technical
 * message when none of them identify a class. A user-facing string that has
 * already been translated is never a classification input (issue #120), so
 * changing the display language can never change the class.
 */
export type ErrorSignals = {
  code?: string;
  status?: number;
  reason?: string;
};

/**
 * Provider `code`/`reason`/`type` tokens (normalized to upper case) mapped to a
 * class. One table serves both structured fields so the two can never drift.
 */
port const CODE_SIGNALS: Record<string, AppErrorCode> = {
  TIMEOUT: 'TIMEOUT',
  REQUEST_TIMEOUT: 'TIMEOUT',
  PERMISSION: 'PERMISSION',
  PERMISSION_ERROR: 'PERMISSION',
  FORBIDDEN: 'PERMISSION',
  PERMISSION_DENIED: 'PERMISSION',
  GATEWAY: 'GATEWAY',
  VALIDATION: 'CONFIG',
  INVALID_REQUEST: 'CONFIG',
  INVALID_REQUEST_ERROR: 'CONFIG',
  UNSUPPORTED: 'CHANNEL_UNAVAILABLE',
  CHANNEL_UNAVAILABLE: 'CHANNEL_UNAVAILABLE',
  CONVERSATION_STATE: 'CONVERSATION_STATE',
  INVALID_CONVERSATION_STATE: 'CONVERSATION_STATE',
  NETWORK: 'NETWORK',
  CONNECTION_ERROR: 'NETWORK',
  AUTH_INVALID: 'AUTH_INVALID',
  UNAUTHORIZED: 'AUTH_INVALID',
  AUTH_EXPIRED: 'AUTH_INVALID',
  AUTHENTICATION_ERROR: 'AUTH_INVALID',
  AUTH_PERMANENT: 'AUTH_PERMANENT',
  INVALID_API_KEY: 'AUTH_PERMANENT',
  API_KEY_INVALID: 'AUTH_PERMANENT',
  KEY_REVOKED: 'AUTH_PERMANENT',
  RATE_LIMIT: 'RATE_LIMIT',
  RATE_LIMITED: 'RATE_LIMIT',
  RATE_LIMIT_EXCEEDED: 'RATE_LIMIT',
  TOO_MANY_REQUESTS: 'RATE_LIMIT',
  BILLING: 'BILLING',
  PAYMENT_REQUIRED: 'BILLING',
  INSUFFICIENT_BALANCE: 'BILLING',
  INSUFFICIENT_QUOTA: 'BILLING',
  QUOTA_EXCEEDED: 'BILLING',
  BILLING_HARD_LIMIT_REACHED: 'BILLING',
  OVERLOADED: 'OVERLOADED',
  OVERLOADED_ERROR: 'OVERLOADED',
  MODEL_OVERLOADED: 'OVERLOADED',
  SERVER_OVERLOADED: 'OVERLOADED',
  MODEL_NOT_FOUND: 'MODEL_NOT_FOUND',
  UNKNOWN_MODEL: 'MODEL_NOT_FOUND',
};

const STATUS_SIGNALS: Record<number, AppErrorCode> = {
  401: 'AUTH_INVALID',
  402: 'BILLING',
  403: 'PERMISSION',
  408: 'TIMEOUT',
  429: 'RATE_LIMIT',
  503: 'OVERLOADED',
  504: 'TIMEOUT',
  529: 'OVERLOADED',
};

export function mapBackendErrorCode(code?: string): AppErrorCode {
  if (typeof code !== 'string') return 'UNKNOWN';
  return CODE_SIGNALS[code.trim().toUpperCase()] ?? 'UNKNOWN';
}

/**
 * Last-resort classification from the untranslated technical message.
 * Only reachable when no structured signal identified a class.
 */
function classifyMessage(message: string): AppErrorCode {
  // Separator-insensitive so `invalid_api_key` / `rate_limit_exceeded` style
  // provider tokens match the same probes as prose.
  const lower = message.toLowerCase().replace(/[_-]+/g, ' ');

  if (
    lower.includes('invalid ipc channel')
    || lower.includes('no handler registered')
    || lower.includes('window is not defined')
    || lower.includes('unsupported')
  ) {
    return 'CHANNEL_UNAVAILABLE';
  }
  if (lower.includes('conversation state') || lower.includes('roles must alternate')) {
    return 'CONVERSATION_STATE';
  }
  if (
    lower.includes('insufficient balance')
    || lower.includes('insufficient_quota')
    || lower.includes('insufficient quota')
    || lower.includes('quota exceeded')
    || lower.includes('exceeded your current quota')
    || lower.includes('billing')
    || lower.includes('credit balance')
    || lower.includes('payment required')
  ) {
    return 'BILLING';
  }
  if (
    lower.includes('invalid api key')
    || lower.includes('api key is invalid')
    || lower.includes('api key was revoked')
    || lower.includes('key has been revoked')
  ) {
    return 'AUTH_PERMANENT';
  }
  if (
    lower.includes('invalid authentication')
    || lower.includes('unauthorized')
    || lower.includes('auth failed')
    || lower.includes('401')
  ) {
    return 'AUTH_INVALID';
  }
  if (lower.includes('model not found') || lower.includes('unknown model')) {
    return 'MODEL_NOT_FOUND';
  }
  if (lower.includes('overloaded')) {
    return 'OVERLOADED';
  }
  if (lower.includes('timeout') || lower.includes('timed out') || lower.includes('abort')) {
    return 'TIMEOUT';
  }
  if (lower.includes('rate limit') || lower.includes('429')) {
    return 'RATE_LIMIT';
  }
  if (
    lower.includes('permission')
    || lower.includes('forbidden')
    || lower.includes('denied')
    || lower.includes('403')
  ) {
    return 'PERMISSION';
  }
  if (
    lower.includes('network')
    || lower.includes('fetch')
    || lower.includes('econnrefused')
    || lower.includes('econnreset')
    || lower.includes('enotfound')
  ) {
    return 'NETWORK';
  }
  if (lower.includes('gateway')) {
    return 'GATEWAY';
  }
  if (lower.includes('config') || lower.includes('invalid') || lower.includes('validation') || lower.includes('400')) {
    return 'CONFIG';
  }

  return 'UNKNOWN';
}

function readStringField(source: Record<string, unknown>, key: string): string | undefined {
  const value = source[key];
  if (typeof value === 'string' && value.trim()) return value.trim();
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  return undefined;
}

function readStatusField(source: Record<string, unknown>, key: string): number | undefined {
  const value = source[key];
  const parsed = typeof value === 'number'
    ? value
    : (typeof value === 'string' && /^\d+$/.test(value.trim()) ? Number(value.trim()) : Number.NaN);
  if (!Number.isFinite(parsed) || parsed < 100 || parsed > 599) return undefined;
  return parsed;
}

/** Walks the error and its nested cause/response/data chain once. */
function collectSignalSources(err: unknown): Array<Record<string, unknown>> {
  const sources: Array<Record<string, unknown>> = [];
  const seen = new Set<unknown>();
  const visit = (value: unknown): void => {
    if (!value || typeof value !== 'object' || seen.has(value)) return;
    seen.add(value);
    const record = value as Record<string, unknown>;
    sources.push(record);
    visit(record.cause);
    visit(record.error);
    visit(record.response);
    visit(record.data);
  };
  visit(err);
  return sources;
}

/**
 * Reads structured signals, most explicit source first: caller-supplied
 * `details` (host-api envelopes, store context) then the throwing object and
 * its nested cause/response chain.
 */
export function readErrorSignals(err: unknown, details?: Record<string, unknown>): ErrorSignals {
  const sources = [...(details ? [details] : []), ...collectSignalSources(err)];
  const signals: ErrorSignals = {};
  for (const source of sources) {
    signals.code ??= readStringField(source, 'code')
      ?? readStringField(source, 'errorCode')
      ?? readStringField(source, 'reasonCode');
    signals.status ??= readStatusField(source, 'status')
      ?? readStatusField(source, 'statusCode')
      ?? readStatusField(source, 'httpStatus');
    signals.reason ??= readStringField(source, 'reason')
      ?? readStringField(source, 'type')
      ?? readStringField(source, 'errorType');
  }
  return signals;
}

function classifySignals(signals: ErrorSignals): AppErrorCode | undefined {
  for (const token of [signals.code, signals.reason]) {
    if (!token) continue;
    const mapped = mapBackendErrorCode(token);
    if (mapped !== 'UNKNOWN') return mapped;
  }
  return signals.status !== undefined ? STATUS_SIGNALS[signals.status] : undefined;
}

function readErrorMessage(err: unknown): string {
  if (err instanceof Error) return err.message;
  if (err && typeof err === 'object') {
    return readStringField(err as Record<string, unknown>, 'message') ?? '';
  }
  return err === undefined || err === null ? '' : String(err);
}

export function normalizeAppError(err: unknown, details?: Record<string, unknown>): AppError {
  if (err instanceof AppError) {
    const requestId = err.requestId
      ?? readStringField(err.details ?? {}, 'requestId');
    return new AppError(
      err.code,
      err.message,
      err.cause ?? err,
      { ...(err.details ?? {}), ...(details ?? {}) },
      requestId,
    );
  }

  const message = readErrorMessage(err);
  const signals = readErrorSignals(err, details);
  // Structured signals win. Only their absence lets the untranslated technical
  // message (or a structured `reason` string) decide the class.
  const code = classifySignals(signals)
    ?? classifyMessage([signals.reason ?? '', message].join(' ').trim());
  return new AppError(
    code,
    message,
    err,
    details,
    readStringField(details ?? {}, 'requestId'),
  );
}
"},{"path":"harness/specs/tasks/harness-gap-error-recovery-next-action.md","content":"# G01: Error recovery and next actions

## Goal

Every `AppErrorCode` has one stable recovery entry containing `retryable`, `scope`, and an optional bounded `action`. The existing `AppError` remains the only application error type and is carried by the existing unified host response envelope.

## Recovery contract

- Only transient self-recovery classes are retryable.
- A retryable entry has the exact action `{ kind: 'retry' }`.
- A non-retryable known error is `user-action-required` and must not use `retry`.
- `UNKNOWN` is not retryable, has no action, and uses `expose-raw-error`. The renderer must expose the original error rather than claim an automatic repair.
- Action kinds are limited to `retry`, `reauthenticate`, `reconfigure`, `open-settings`, and `contact-support`.
- An action may contain only `kind` and an optional `target` from the closed target vocabulary. Actions are descriptive data and never executable instructions.

## Required table

| Code | Retryable | Scope | Action |
| --- | --- | --- | --- |
| `AUTH_INVALID` | no | `user-action-required` | `reauthenticate` / `authentication` |
| `AUTH_PERMANENT` | no | `user-action-required` | `reauthenticate` / `authentication` |
| `TIMEOUT` | yes | `self-retry` | `retry` |
| `RATE_LIMIT` | yes | `self-retry` | `retry` |
| `PERMISSION` | no | `user-action-required` | `open-settings` / `permissions` |
| `CHANNEL_UNAVAILABLE` | yes | `self-retry` | `retry` |
| `CONVERSATION_STATE` | no | `user-action-required` | `reconfigure` / `conversation` |
| `NETWORK` | yes | `self-retry` | `retry` |
| `CONFIG` | no | `user-action-required` | `reconfigure` / `configuration` |
| `GATEWAY` | yes | `self-retry` | `retry` |
| `BILLING` | no | `user-action-required` | `open-settings` / `billing` |
| `OVERLOADED` | yes | `self-retry` | `retry` |
| `MODEL_NOT_FOUND` | no | `user-action-required` | `reconfigure` / `model` |
| `UNKNOWN` | no | `expose-raw-error` | none |

## Implementation acceptance

- `APP_ERROR_RECOVERY` is exhaustively keyed by `AppErrorCode`.
- Every constructed or normalized `AppError` exposes `retryable` and `nextAction` consistent with the table.
- `nextAction` has no `command`, `script`, `shell`, `exec`, or `argv` member.
- Existing constructor and normalization signatures remain compatible.
- Existing `HostResponse`/`AppError` envelope behavior remains unchanged.
"},{"path":"docs/dev/harness-gap-closure/g01-error-recovery-next-action.md","content":"# G01 error recovery and next-action closure

## Overview

G01 adds stable recovery metadata to the existing unified error model. It does not introduce another error class or another response envelope.

The exported `APP_ERROR_RECOVERY` table is the single recovery governance source. Its keys cover every member of `AppErrorCode`, so adding an error code without making a recovery decision fails the type-level exhaustive record check.

## Public types

`AppErrorNextAction` is a closed discriminated union. Its `kind` is one of:

- `retry`
- `reauthenticate`
- `reconfigure`
- `open-settings`
- `contact-support`

An action can optionally carry a `target`, but that target is also a closed union. This makes it impossible to represent an arbitrary command, shell expression, script, executable name, argument vector, or other raw instruction as a next action.

`AppErrorRecoveryScope` records who owns recovery:

- `self-retry`: the host may safely repeat the same transient operation.
- `user-action-required`: a user-controlled change is required.
- `support-required`: recovery needs operator or support intervention.
- `expose-raw-error`: no trustworthy automatic recovery exists.

## Classification decisions

Transient availability and capacity failures (`TIMEOUT`, `RATE_LIMIT`, `CHANNEL_UNAVAILABLE`, `NETWORK`, `GATEWAY`, and `OVERLOADED`) are the only retryable classes. Each has exactly `{ kind: 'retry' }`.

Authentication, permission, conversation, configuration, billing, and model failures are not assumed to be repaired by repeating the same operation. They expose a fixed user action with a bounded target where applicable.

`UNKNOWN` deliberately has no `nextAction`. Its scope is `expose-raw-error`: the original error must remain visible to the user or diagnostic renderer. The model must not manufacture a plausible-looking recovery action for an unrecognized error.

## Integration

`AppError` continues to use its existing constructor shape. It now exposes readonly `retryable` and `nextAction` fields populated from the recovery table. `normalizeAppError` continues to return `AppError` and preserves the existing cause, details, request id, and classification behavior.

No second error type or envelope is introduced. Existing host response handling can therefore continue to render the established `HostResponse`/`AppError` path while consuming the new recovery metadata.

## Verification checklist

1. Check that the recovery table contains exactly one entry for every `APP_ERROR_CODES` member.
2. Check that each retryable entry has action `{ kind: 'retry' }` and each non-retryable known entry has a non-retry action.
3. Check that `UNKNOWN` has no action and remains non-retryable.
4. Check that action objects contain no executable fields.
5. Run the focused error-model tests, web type checking, scoped lint, harness validation/dry-run, and comms replay/compare.
6. Run the credential scanner and verify that `SHA256SUMS` can be read back.
"}]}

